EMOJI_TO_LUCIDE = {
    "🇪🇺": "shield-check",
    "🏥": "activity",
    "🏦": "building-2",
    "🛡️": "lock",
    "📄": "file-text",
    "🔒": "lock",
    "🚨": "shield-alert",
    "👤": "user-check",
    "🤝": "handshake",
    "⏳": "clock",
    "ℹ️": "info",
    "⚠️": "alert-triangle",
}

def clean_icon_name(raw_icon):
    if not raw_icon:
        return "file-text"
    val = str(raw_icon).strip()
    return EMOJI_TO_LUCIDE.get(val, val)

def lucide_html(name, size=24, class_name=""):
    key = clean_icon_name(name)
    template = LUCIDE_SVGS.get(key, LUCIDE_SVGS.get("file-text", LUCIDE_SVGS["info"]))
    return template.format(size=size, class_name=class_name)

def lucide_icon(name, size=24, class_name=""):
    return ui.html(lucide_html(name, size=size, class_name=class_name))
